/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    SURVIVAL_CALCULATORS
 * depends    src/calculators/types
 * used by    src/calculators/index, src/calculators/registry
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import type { CalculatorSpec } from './types'

/**
 * The wave survival model, declared so an agent can run it by name.
 *
 * Five calculators, in the order they build on each other: healing per wave, damage reaching the
 * tower, a fit of the account's own runs, a predicted death wave, and upgrades ranked by waves
 * gained per coin. The first two are pure and take a state. The last three take a save — pass
 * `savePath` to `calc_run` and it fills `root` — and rest on a FITTED calibration: read the
 * leave-one-out error beside any number they return.
 */

const MECH = 'src/mechanics'
const SAVE = 'src/save'

const STATE_DESCRIBES
  = 'a SurvivalState: tier, workshop `levels`, resolved `bonuses`, `spawn`, `freeUpgrades`, `deathWave`, '
  + '`packageAfterBoss`, `waveSkipChance`, `effectiveDamage`, `effectiveDamageGrowthPerWave`, `projectileKillShare`'

const CALIBRATION_DESCRIBES
  = '{ curves: { melee, ranged, bossElite: { logHits, exponent } }, healthScale, referenceRatio, referenceWave }; '
  + 'the placeholder default when left out'

const ASSUMPTIONS_DESCRIBES
  = 'overrides for the unverified mechanics: damageTakenIsPostMitigation, maxHealthGrowthHealsCurrent, '
  + 'packagesOnSkippedWaves, lifestealActive'

export const SURVIVAL_CALCULATORS: readonly CalculatorSpec[] = [
  {
    id: 'survival.healingForWave',
    title: 'The four heals of one wave, each after its own clamp',
    entry: 'mechanics',
    module: `${MECH}/survival/healing.ts`,
    symbol: 'healingForWave',
    because:
      'Healing is a clamped rate, not a bigger pool. A package landing on a tower already at its '
      + 'overheal cap heals nothing, so the same Recovery Amount heals very different totals in '
      + 'different runs. This returns the heals separately so each clamp can be seen on its own.',
    params: [
      { name: 'state', kind: 'object', describes: STATE_DESCRIBES },
      { name: 'wave', kind: 'number', unit: 'waves', describes: 'the wave, from 1' },
      {
        name: 'options',
        kind: 'object',
        optional: true,
        describes: 'what happened in the wave; an average played wave from full health when left out',
        fields: [
          { name: 'health', kind: 'number', describes: 'health before healing; full health by default' },
          { name: 'levels', kind: 'object', describes: 'in-run levels by upgrade name; the workshop levels by default' },
          { name: 'packages', kind: 'number', describes: 'packages that arrived; the expected number by default' },
          { name: 'seconds', kind: 'number', unit: 'seconds', describes: 'seconds regen ran; the wave length by default' },
          { name: 'projectileDamage', kind: 'number', describes: 'projectile damage dealt, which lifesteal reads' },
          { name: 'deathWaveFraction', kind: 'number', unit: 'fraction', describes: 'Death Wave bonus already held, as a share of base max health' },
          { name: 'healingBlocked', kind: 'boolean', describes: 'a Vampire is draining the tower: regen and lifesteal are off' },
          { name: 'lifestealActive', kind: 'boolean', describes: 'whether lifesteal heals at all; true by default' },
        ],
      },
    ],
    returns: { kind: 'object', unit: 'health', describes: '{ packages, lifesteal, regen, deathWave, healthAfter, maxHealth }' },
    invariants: [
      'healthAfter never exceeds Max Recovery x maxHealth unless health started above it',
      'lifesteal and regen never raise health past maxHealth, and never lower it',
      'with zero packages, `packages` is 0 whatever Recovery Amount is',
      'deathWave raises maxHealth and healthAfter by the same amount',
    ],
    reads: ['survival.state'],
    produces: ['survival.healing'],
    dependsOn: [],
  },
  {
    id: 'survival.incomingDamageForWave',
    title: 'Damage reaching the tower in one wave, by enemy class',
    entry: 'mechanics',
    module: `${MECH}/survival/incoming-damage.ts`,
    symbol: 'incomingDamageForWave',
    because:
      'The SDK knows how hard each enemy hits; the missing number was how many hits land. This '
      + 'multiplies spawns, hits per enemy, damage per hit after level skips, and what mitigation '
      + 'leaves. Hits per enemy is a FITTED curve of how long enemies outlive the tower\'s damage.',
    params: [
      { name: 'state', kind: 'object', describes: STATE_DESCRIBES },
      { name: 'wave', kind: 'number', unit: 'waves', describes: 'the wave, from 1' },
      { name: 'calibration', kind: 'object', optional: true, describes: CALIBRATION_DESCRIBES },
      {
        name: 'context',
        kind: 'object',
        optional: true,
        describes: 'where the wave sits in a run; the workshop alone, with no skips, when left out',
        fields: [
          { name: 'levels', kind: 'object', describes: 'in-run levels by upgrade name' },
          { name: 'attackSkips', kind: 'number', describes: 'enemy attack level skips so far' },
          { name: 'healthSkips', kind: 'number', describes: 'enemy health level skips so far' },
          { name: 'deathWaveFraction', kind: 'number', unit: 'fraction', describes: 'Death Wave bonus held, as a share of base max health' },
        ],
      },
    ],
    returns: { kind: 'object', unit: 'health', describes: '{ byClass: { basic, fast, tank, ranged, boss, elite }, mitigated, total }' },
    invariants: [
      'total is the sum of byClass',
      'byClass.boss is 0 off a boss wave',
      'raising Defense % never raises total',
      'more attack level skips never raise total',
    ],
    reads: ['survival.state', 'survival.calibration'],
    produces: ['survival.incomingDamage'],
    dependsOn: [],
  },
  {
    id: 'survival.calibrateFromHistory',
    title: 'Fit the hit curves to the account\'s own stored runs',
    entry: 'save',
    module: `${SAVE}/survival/from-save.ts`,
    symbol: 'calibrateSurvivalFromHistory',
    because:
      'Every save carries its last thirty runs with damage taken, healing and death wave. This '
      + 'fits the model to them, each run with the state it was played with, and reports the '
      + 'leave-one-out error — the number that says how far to trust a prediction.',
    params: [
      { name: 'root', kind: 'object', describes: 'the decoded save, or a stored snapshot; calc_run fills it from savePath' },
      {
        name: 'options',
        kind: 'object',
        optional: true,
        describes: 'which runs to fit and how hard to search',
        fields: [
          { name: 'snapshots', kind: 'object', describes: 'earlier readings of the account, as an array of decoded saves or stored snapshots' },
          { name: 'tier', kind: 'number', describes: 'the tier to fit; the most recent farming run\'s by default' },
          { name: 'runModes', kind: 'object', describes: 'afk, active or exclude by run battleDate; run records do not say' },
          { name: 'unlabelledRuns', kind: 'string', describes: 'what a run not in runModes is taken as: afk (default), active or exclude' },
          { name: 'unbracketedRuns', kind: 'string', describes: 'skip (default) or nearest, for a run no pair of unchanged readings brackets' },
          { name: 'cashPolicies', kind: 'object', describes: '{ targetLevels, byWave } by battleDate, for active runs' },
          { name: 'minWave', kind: 'number', unit: 'waves', describes: 'leave out shorter runs; 100 by default' },
          { name: 'maxRuns', kind: 'number', describes: 'use at most this many of the most recent runs' },
          { name: 'seeds', kind: 'number', describes: 'seeded runs per real run while fitting; 24 by default' },
          { name: 'baseSeed', kind: 'number', describes: 'first seed; 1 by default' },
          { name: 'subSteps', kind: 'number', describes: 'sub-steps per wave; 10 by default' },
          { name: 'passes', kind: 'number', describes: 'search passes; 3 by default, 0 to predict from `start` without fitting' },
          { name: 'start', kind: 'object', describes: 'the calibration to start from' },
          { name: 'skipLeaveOneOut', kind: 'boolean', describes: 'skip the hold-out refits' },
        ],
      },
    ],
    returns: {
      kind: 'object',
      nullable: true,
      describes: '{ calibration, perRun: [{ runDate, wave, predictedWave, error, … }], leaveOneOutError, loss, tier, runsUsed, skipped, warnings }, or null with no workshop to read',
    },
    invariants: [
      'every run is in perRun or in skipped with a reason',
      'leaveOneOutError is the mean of |perRun.error|, or null with fewer than two runs',
      'the same save, options and seeds give the same calibration',
    ],
    reads: ['save.battleHistory', 'save.workshop'],
    produces: ['survival.calibration'],
    dependsOn: [],
  },
  {
    id: 'survival.simulateRun',
    title: 'Predict the death wave of the account in a save',
    entry: 'save',
    module: `${SAVE}/survival/from-save.ts`,
    symbol: 'simulateSurvivalRunFromSave',
    because:
      'Plays the run forward wave by wave on many seeds and reports the median death wave with '
      + 'its 10th and 90th percentiles. AFK mode is workshop levels plus free upgrades; active mode '
      + 'also follows a declared level schedule. Without a fitted calibration the number is a placeholder.',
    params: [
      { name: 'root', kind: 'object', describes: 'the decoded save, or a stored snapshot; calc_run fills it from savePath' },
      {
        name: 'options',
        kind: 'object',
        optional: true,
        describes: 'how to simulate',
        fields: [
          { name: 'tier', kind: 'number', describes: 'the tier; the most recent farming run\'s by default' },
          { name: 'mode', kind: 'string', describes: 'afk (default) or active' },
          { name: 'calibration', kind: 'object', describes: CALIBRATION_DESCRIBES },
          { name: 'seeds', kind: 'number', describes: 'seeded runs; 200 by default' },
          { name: 'baseSeed', kind: 'number', describes: 'first seed; 1 by default' },
          { name: 'rows', kind: 'boolean', describes: 'return one row per wave of the median run' },
          { name: 'cashPolicy', kind: 'object', describes: 'active mode: { targetLevels, byWave }' },
          { name: 'assumptions', kind: 'object', describes: ASSUMPTIONS_DESCRIBES },
        ],
      },
    ],
    returns: {
      kind: 'object',
      nullable: true,
      describes: '{ deathWave: { p10, median, p90 }, endedBy: { attrition, burst, survived }, damageTaken, packageHeal, packages, seeds, assumptions, tier, warnings, rows? }, or null',
    },
    invariants: [
      'deathWave.p10 <= deathWave.median <= deathWave.p90',
      'endedBy shares sum to 1',
      'the same save, options and seeds give the same result',
      'rows is present only when asked for',
    ],
    reads: ['save.workshop', 'save.battleHistory', 'survival.calibration'],
    produces: ['survival.deathWave'],
    dependsOn: [],
  },
  {
    id: 'survival.rankUpgrades',
    title: 'Rank workshop upgrades by waves gained per coin',
    entry: 'save',
    module: `${SAVE}/survival/from-save.ts`,
    symbol: 'rankSurvivalUpgradesFromSave',
    because:
      'The SDK prices every survival upgrade and could not say which adds more waves. This '
      + 'simulates the account with each candidate bought, on the same seeds, and divides the '
      + 'waves gained by the Workshop price, discount labs included.',
    params: [
      { name: 'root', kind: 'object', describes: 'the decoded save, or a stored snapshot; calc_run fills it from savePath' },
      { name: 'candidates', kind: 'object', describes: 'an array of { stat, toLevel }; stat is a workshop upgrade name such as "Recovery Amount"' },
      {
        name: 'options',
        kind: 'object',
        optional: true,
        describes: 'how to simulate',
        fields: [
          { name: 'tier', kind: 'number', describes: 'the tier; the most recent farming run\'s by default' },
          { name: 'mode', kind: 'string', describes: 'afk (default) or active' },
          { name: 'calibration', kind: 'object', describes: CALIBRATION_DESCRIBES },
          { name: 'seeds', kind: 'number', describes: 'seeded runs per candidate; 200 by default' },
          { name: 'baseSeed', kind: 'number', describes: 'first seed; 1 by default' },
          { name: 'cashPolicy', kind: 'object', describes: 'active mode: { targetLevels, byWave }' },
          { name: 'assumptions', kind: 'object', describes: ASSUMPTIONS_DESCRIBES },
        ],
      },
    ],
    returns: {
      kind: 'object',
      nullable: true,
      describes: '{ baseline, ranked: [{ stat, fromLevel, toLevel, coins, medianWavesGained, wavesPerBillionCoins, deathWave }], assumptions, tier, warnings }, or null',
    },
    invariants: [
      'ranked is sorted by wavesPerBillionCoins, highest first, unpriced last',
      'coins is what workshop.upgradePrice returns for the same levels and the tab\'s discount',
      'a candidate at or below the current level gains 0 waves and costs 0',
    ],
    reads: ['save.workshop', 'save.battleHistory', 'survival.calibration'],
    produces: ['survival.ranking'],
    dependsOn: [],
  },
]
